// Deterministic, general verification guidance. These steps are chosen by fixed rules from the
// assessment label and the rule-based signals; they are not generated by a model, contain no
// links, and never recommend a financial action.

import type { AssessedClaimResult, ManipulationSignalType } from "@/lib/types";

const MAX_STEPS = 5;

const ASSESSMENT_STEPS: Record<AssessedClaimResult["assessment"]["assessment"], string[]> = {
  Supported: [
    "Open the cited sources and confirm they refer to the same organisation, product, and time period as the message.",
    "Check that the source is current; older pages may no longer apply.",
  ],
  Contradicted: [
    "Open the cited sources and compare their wording with the message yourself.",
    "Be cautious about acting on content whose claims conflict with the sources found.",
  ],
  "Needs more evidence": [
    "Open the original source pages rather than relying on search snippets.",
    "Look for an official announcement from the organisation named in the claim.",
  ],
  Unverified: [
    "Look for an official announcement from the organisation named in the claim.",
    "Treat the claim as unconfirmed. Not finding evidence here does not show that it is false.",
  ],
};

const SIGNAL_STEPS: Partial<Record<ManipulationSignalType, string>> = {
  AUTHORITY_CLAIM:
    "Confirm any claimed registration or approval directly on the relevant regulator's official website, such as SEBI or RBI.",
  GUARANTEED_RETURN:
    "Be wary of promised or guaranteed returns. Ask for official documents that explain the risks.",
  URGENCY:
    "Take your time. Deadlines that demand an immediate decision are a common pressure tactic.",
  SCARCITY_FOMO:
    "Limited slots or seats are a common pressure tactic. Scarcity is not evidence that an offer is genuine.",
  INSIDER_SECRET_LANGUAGE:
    "Be wary of “insider” or secret information. Legitimate disclosures are made publicly.",
  TESTIMONIAL_SOCIAL_PROOF_PRESSURE:
    "Testimonials and screenshots of profits are not independent evidence.",
  UNSUPPORTED_STATISTICAL_CLAIM:
    "Ask where any figures come from, and check them against the original source.",
  EXAGGERATED_CERTAINTY:
    "Be wary of language that leaves no room for risk or uncertainty.",
};

export function nextStepsFor(result: AssessedClaimResult): string[] {
  const steps = [...ASSESSMENT_STEPS[result.assessment.assessment]];
  for (const signal of result.manipulation_signals) {
    const step = SIGNAL_STEPS[signal.signal_type];
    if (step && !steps.includes(step)) steps.push(step);
  }
  return steps.slice(0, MAX_STEPS);
}
